import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/GET.md","filePath":"manual-en/GET.md","lastUpdated":1785684581000}'),d={name:"manual-en/GET.md"};function s(i,e,c,r,l,m){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h3 id="_9-3-get" tabindex="-1">9.3 GET <a class="header-anchor" href="#_9-3-get" aria-label="Permalink to &quot;9.3 GET&quot;">​</a></h3><pre><code>GET
        /FILE={’file_name’,file_handle}
        /DROP=var_list
        /KEEP=var_list
        /RENAME=(src_names=target_names)…
        /ENCODING=’encoding’
</code></pre><p><code>GET</code> clears the current dictionary and active dataset and replaces them with the dictionary and data from a specified file.</p><p>The <code>FILE</code> subcommand is the only required subcommand. Specify the SPSS system file, SPSS/PC+ system file, or SPSS portable file to be read as a string file name or a file handle (see <a href="./File-Handles">File Handles</a>).</p><p>By default, all the variables in a file are read. The DROP subcommand can be used to specify a list of variables that are not to be read. By contrast, the <code>KEEP</code> subcommand can be used to specify variable that are to be read, with all other variables not read.</p><p>Normally variables in a file retain the names that they were saved under. Use the <code>RENAME</code> subcommand to change these names. Specify, within parentheses, a list of variable names followed by an equals sign (‘=’) and the names that they should be renamed to. Multiple parenthesized groups of variable names can be included on a single <code>RENAME</code> subcommand. Variables’ names may be swapped using a <code>RENAME</code> subcommand of the form <code>/RENAME=(A B=B A)</code>.</p><p>Alternate syntax for the <code>RENAME</code> subcommand allows the parentheses to be eliminated. When this is done, only a single variable may be renamed at once. For instance, <code>/RENAME=A=B</code>. This alternate syntax is deprecated.</p><p><code>DROP</code>, <code>KEEP</code>, and <code>RENAME</code> are executed in left-to-right order. Each may be present any number of times. <code>GET</code> never modifies a file on disk. Only the active dataset read from the file is affected by these subcommands.</p><p>PSPP automatically detects the encoding of string data in the file, when possible. The character encoding of old SPSS system files cannot always be guessed correctly, and SPSS/PC+ system files do not include any indication of their encoding. Specify the <code>ENCODING</code> subcommand with an IANA character set name as its string argument to override the default. Use <code>SYSFILE INFO</code> to analyze the encodings that might be valid for a system file. The <code>ENCODING</code> subcommand is a PSPP extension.</p><p><code>GET</code> does not cause the data to be read, only the dictionary. The data is read later, when a procedure is executed.</p><p>Use of <code>GET</code> to read a portable file is a PSPP extension.</p>`,11)])])}const p=a(d,[["render",s]]);export{f as __pageData,p as default};
